//! Family names resolved like Qt's DirectWrite font database against real Qt 6.12
//! (`tests/data/directwrite_families_golden.txt`, regenerated by
//! `tests/data/gen_directwrite_families_golden.py`): the GDI-compatible names of styled faces
//! ("Segoe UI Semibold", "Arial Narrow", "Calibri Light"), the named instances of variable fonts
//! ("Segoe UI Variable Text", "Bahnschrift SemiBold Condensed", "Cascadia Code SemiLight") and
//! symbol-encoded fonts (Wingdings), at device pixel ratios 1 and 1.25: advances, average width,
//! line metrics and whole strings.
//!
//! The system fonts are compared only when the file on this machine is the one the golden was
//! measured with (size and hash in the golden). The ratio is process-wide state.
#![cfg(windows)]

use ferrokit_gui::geometry::primitives::PointF;
use ferrokit_gui::paint::{Painter, Pen, Pixmap};
use ferrokit_gui::text::directwrite_face::is_available;
use ferrokit_gui::text::font::{Font, FontWeight};
use ferrokit_gui::text::font_database::set_application_device_pixel_ratio;
use ferrokit_gui::text::font_metrics::FontMetrics;
use ferrokit_gui::text::smoothing::TextSmoothing;
use ferrokit_gui::tiny_skia::Color;

const GOLDEN: &str = include_str!("data/directwrite_families_golden.txt");

fn fnv1a64(data: &[u8]) -> u64 {
    data.iter().fold(0xcbf2_9ce4_8422_2325u64, |h, &b| {
        (h ^ u64::from(b)).wrapping_mul(0x0100_0000_01b3)
    })
}

fn text(id: &str) -> &'static str {
    match id {
        "a" => "Hamburgefonstiv 0123",
        "b" => "AVAWTo.,:;",
        "c" => "iiiiiWWW The quick brown fox",
        other => panic!("no text {other}"),
    }
}

fn fixed64(value: f32) -> i64 {
    let fixed = f64::from(value) * 64.0;
    assert_eq!(
        fixed,
        fixed.round(),
        "{value} is not a whole number of 1/64 px"
    );
    fixed as i64
}

fn draw(font: &Font, px: u32, text: &str, dpr: f32) -> (u32, u32, u64) {
    let (w, h) = (360.0 * dpr, ((px * 2 + 15) / 4 * 4) as f32 * dpr);
    let mut pixmap = Pixmap::with_dpr(w.round() as u32, h.round() as u32, dpr).expect("pixmap");
    pixmap.fill(Color::from_rgba8(255, 255, 255, 255));
    {
        let mut painter = Painter::begin(&mut pixmap);
        painter.set_text_smoothing(TextSmoothing {
            cleartype: true,
            gamma: 1.2,
        });
        painter.set_pen(Some(Pen::new(Color::from_rgba8(0, 0, 0, 255), 1.0)));
        painter.draw_text(PointF::new(6.0, px as f32 + 6.0), text, font);
    }
    (
        pixmap.physical_width(),
        pixmap.physical_height(),
        fnv1a64(pixmap.data()),
    )
}

fn hex(field: &str) -> u64 {
    u64::from_str_radix(field, 16).expect("hash")
}

#[test]
fn family_names_of_styled_faces_and_variable_instances_are_identical_to_qt() {
    if !is_available() {
        return;
    }
    let mut compared = 0;
    let mut failures = Vec::new();
    let mut installed = false;
    for line in GOLDEN
        .lines()
        .filter(|l| !l.starts_with('#') && !l.trim().is_empty())
    {
        let fields: Vec<&str> = line.split(' ').collect();
        if fields[0] == "sysfont" {
            let (size, hash) = (fields[2].parse::<usize>().unwrap(), hex(fields[3]));
            let dir = std::env::var("WINDIR").unwrap_or_else(|_| "C:/Windows".to_string());
            installed = std::fs::read(format!("{dir}/Fonts/{}", fields[1]))
                .ok()
                .is_some_and(|bytes| bytes.len() == size && fnv1a64(&bytes) == hash);
            if !installed {
                eprintln!("skipping {}: not installed as measured", fields[1]);
            }
            continue;
        }
        if !installed {
            continue;
        }
        // `fam <dpr> <family> <weight> <px> ...`
        let dpr: f32 = fields[1].parse().expect("dpr");
        let family = fields[2].replace('_', " ");
        let weight: u32 = fields[3].parse().expect("weight");
        let px: u32 = fields[4].parse().expect("size");
        set_application_device_pixel_ratio(dpr);
        let font = Font::new(&family, px as f32).with_weight(if weight >= 600 {
            FontWeight::Bold
        } else {
            FontWeight::Normal
        });
        let rest = &fields[5..];
        let metrics = FontMetrics::from_font(&font);
        let (got, want) = match rest[0] {
            "adv" => {
                let advance = metrics.horizontal_advance_exact(text(rest[1]), &font);
                (format!("{}", fixed64(advance)), rest[2].to_string())
            }
            "avg" => (
                format!("{}", fixed64(metrics.average_char_width)),
                rest[1].to_string(),
            ),
            "met" => (
                format!(
                    "{} {} {}",
                    metrics.ascent, metrics.descent, metrics.line_gap
                ),
                rest[1..].join(" "),
            ),
            "draw" => {
                let (w, h, hash) = draw(&font, px, text(rest[1]), dpr);
                (
                    format!("{w}x{h} {hash:016x}"),
                    format!("{}x{} {:016x}", rest[2], rest[3], hex(rest[4])),
                )
            }
            other => panic!("golden line {other}"),
        };
        compared += 1;
        if got != want {
            failures.push(format!("{line}: {got}, Qt {want}"));
        }
    }
    set_application_device_pixel_ratio(1.0);
    assert!(
        failures.is_empty(),
        "{} of {compared} differ from Qt:\n{}",
        failures.len(),
        failures.join("\n")
    );
}
